  j constant jsonb := $j$[
{"id":"26ec7037-0696-4a6f-be0c-669f8b58ccf5","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"es","slug":"arroz-frito","public_path":"/arroz-frito","source_url":null,"title":"Arroz frito con vegetales","excerpt":"Arroz frito con vegetales al estilo wok: arroz suelto con zanahoria, arvejas, huevo y cebollín, aliñado con salsa de soja y aceite de sésamo. Para 4 personas, listo en 25 minutos.","summary":"El arroz frito con vegetales se prepara salteando zanahoria y arvejas en un wok muy caliente, cuajando huevo batido, añadiendo ajo y cebollín y mezclando todo con arroz cocido frío. Se aliña con salsa de soja y unas gotas de aceite de sésamo.\n\nLo mejor es usar arroz cocido de la víspera, que está seco y se separa bien. Todo el salteado dura unos 10 minutos. Rinde 4 porciones como guarnición.","category":"Guarniciones","difficulty":"Fácil","course":"Acompañamiento","cuisine":"Asiática","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["arroz frito con vegetales","receta de arroz frito","cómo hacer arroz frito","arroz frito con huevo","arroz frito estilo chino","arroz frito casero","arroz frito fácil"],"ingredients":[{"name":"arroz blanco cocido y frío","amount":"600","unit":"g","group":"Para el arroz"},{"name":"zanahoria","amount":"1","unit":"","group":"Para el arroz"},{"name":"arvejas","amount":"100","unit":"g","group":"Para el arroz"},{"name":"huevos","amount":"2","unit":"","group":"Para el arroz"},{"name":"dientes de ajo","amount":"2","unit":"","group":"Para el arroz"},{"name":"cebollines","amount":"3","unit":"","group":"Para el arroz"},{"name":"aceite vegetal","amount":"2","unit":"cucharada","group":"Para el arroz"},{"name":"salsa de soja","amount":"3","unit":"cucharada","group":"Para el arroz"},{"name":"aceite de sésamo","amount":"1","unit":"cucharadita","group":"Para el arroz"},{"name":"sal","amount":"1","unit":"pizca","group":"Para el arroz"},{"name":"pimienta negra molida","amount":"1","unit":"pizca","group":"Para el arroz"}],"steps":[{"title":"Prepara los ingredientes","content":"Corta 1 zanahoria en cubitos, rebana 3 cebollines y pica 2 dientes de ajo. Desgrana con un tenedor 600 g de arroz cocido frío, de la víspera.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Arroz frito con vegetales: Prepara los ingredientes"},{"title":"Saltea las verduras","content":"Calienta 2 cucharadas de aceite en un wok a fuego alto y saltea la zanahoria y 100 g de arvejas durante 3 minutos.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Arroz frito con vegetales: Saltea las verduras"},{"title":"Añade el huevo","content":"Empuja las verduras a un lado, vierte 2 huevos batidos en el hueco y revuelve hasta que cuajen, 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Arroz frito con vegetales: Añade el huevo"},{"title":"Añade el ajo y el cebollín","content":"Añade el ajo y la mitad del cebollín y saltea 30 segundos.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Arroz frito con vegetales: Añade el ajo y el cebollín"},{"title":"Agrega el arroz","content":"Agrega el arroz frío y saltea 4 minutos, deshaciendo los grumos con la espátula.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Arroz frito con vegetales: Agrega el arroz"},{"title":"Condimenta","content":"Vierte 3 cucharadas de salsa de soja y 1 cucharadita de aceite de sésamo y mezcla 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Arroz frito con vegetales: Condimenta"},{"title":"Rectifica la sazón","content":"Prueba y rectifica con sal y pimienta; la salsa de soja ya sala, así que añade poca.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Arroz frito con vegetales: Rectifica la sazón"},{"title":"Sirve","content":"Sirve en un bol con el resto del cebollín por encima.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Arroz frito con vegetales: Sirve"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Arroz frito con vegetales"}],"notes":"El arroz recién hecho está húmedo y se apelmaza; usa arroz cocido de la víspera y guárdalo en la nevera. Cocina con el fuego bien fuerte y sin llenar demasiado el wok, para que el arroz se dore en lugar de cocerse al vapor. Puedes añadir pollo, camarones o jamón cocido en cubitos. Se conserva en la nevera hasta 3 días y se recalienta en la sartén con unas gotas de agua.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 600 g de arroz blanco cocido, 80 g de zanahoria, 100 g de arvejas, 100 g de huevo (2 huevos), 6 g de ajo, 45 g de cebollín, 28 g de aceite de soja, 48 g de salsa de soja y 4,5 g de aceite de sésamo. La sal y la pimienta finales no se cuentan.","note":"Estimación por porción. El arroz se calcula como arroz blanco de grano largo cocido. El sodio procede casi todo de la salsa de soja y sube si añades sal al final.","inputs":[{"fdc_id":"168878","description":"Rice, white, long-grain, regular, enriched, cooked (600 g de arroz cocido frío)","grams":600,"per100":{"calories":130,"protein_g":2.69,"carbs_g":28.17,"fat_g":0.28,"saturated_fat_g":0.077,"fiber_g":0.4,"sodium_mg":1}},{"fdc_id":"170393","description":"Carrots, raw (1 zanahoria ≈ 80 g)","grams":80,"per100":{"calories":41,"protein_g":0.93,"carbs_g":9.58,"fat_g":0.24,"saturated_fat_g":0.037,"fiber_g":2.8,"sodium_mg":69}},{"fdc_id":"170419","description":"Peas, green, raw (100 g de arvejas)","grams":100,"per100":{"calories":81,"protein_g":5.42,"carbs_g":14.45,"fat_g":0.4,"saturated_fat_g":0.067,"fiber_g":5.7,"sodium_mg":5}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh (2 huevos grandes ≈ 100 g)","grams":100,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"169230","description":"Garlic, raw (2 dientes ≈ 6 g)","grams":6,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"170005","description":"Onions, spring or scallions (includes tops and bulb), raw (3 cebollines ≈ 45 g)","grams":45,"per100":{"calories":32,"protein_g":1.83,"carbs_g":7.34,"fat_g":0.19,"saturated_fat_g":0.032,"fiber_g":2.6,"sodium_mg":16}},{"fdc_id":"172336","description":"Oil, soybean, salad or cooking (2 cucharadas ≈ 28 g)","grams":28,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":15.65,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"174277","description":"Soy sauce made from soy and wheat (shoyu) (3 cucharadas ≈ 48 g)","grams":48,"per100":{"calories":53,"protein_g":8.14,"carbs_g":4.93,"fat_g":0.57,"saturated_fat_g":0.073,"fiber_g":0.8,"sodium_mg":5493}},{"fdc_id":"171016","description":"Oil, sesame, salad or cooking (1 cucharadita ≈ 4,5 g)","grams":4.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":14.2,"fiber_g":0,"sodium_mg":0}}]},"seo":{"title":"Arroz frito con vegetales, fácil y suelto | Manual de Cocina","description":"Arroz frito con vegetales al estilo wok, con zanahoria, arvejas, huevo y salsa de soja. Para 4 personas, listo en 25 minutos. Receta paso a paso.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"¿Por qué el arroz frito se hace con arroz de la víspera?","a":"El arroz recién cocido tiene demasiada humedad y se apelmaza. El arroz frío y reposado está más seco, se separa en granos y se dora mejor en el wok."},{"q":"¿Se puede hacer arroz frito sin wok?","a":"Sí. Usa una sartén grande y ancha a fuego alto y cocina en tandas pequeñas, para que el arroz no se cueza al vapor."},{"q":"¿Cuánto dura el arroz frito y cómo se recalienta?","a":"Hasta 3 días en la nevera en un recipiente cerrado. Recaliéntalo en una sartén con unas gotas de agua hasta que esté caliente por completo."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"fe6cc8b0-350b-5632-bb39-c455369a4ed8","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"de","slug":"gebratener-reis-mit-gemuese","public_path":"/de/gebratener-reis-mit-gemuese","source_url":null,"title":"Gebratener Reis mit Gemüse","excerpt":"Gebratener Reis mit Gemüse aus dem Wok: körniger Reis mit Karotte, Erbsen, Ei und Frühlingszwiebeln, mit Sojasauce und Sesamöl abgeschmeckt. Für 4 Personen, fertig in 25 Minuten.","summary":"Für den gebratenen Reis mit Gemüse werden Karotte und Erbsen im sehr heißen Wok angebraten, verquirltes Ei gestockt, Knoblauch und Frühlingszwiebeln zugegeben und alles mit kaltem, gekochtem Reis vermengt. Abgeschmeckt wird mit Sojasauce und ein paar Tropfen Sesamöl.\n\nAm besten gelingt er mit Reis vom Vortag, der trocken ist und sich gut lockert. Das Braten dauert etwa 10 Minuten. Ergibt 4 Portionen als Beilage.","category":"Beilagen","difficulty":"Einfach","course":"Beilage","cuisine":"Asiatisch","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["gebratener Reis mit Gemüse","gebratener Reis Rezept","gebratener Reis selber machen","gebratener Reis mit Ei","gebratener Reis chinesisch","Wok Reis","arroz frito con vegetales"],"ingredients":[{"name":"gekochter, kalter weißer Reis","amount":"600","unit":"g","group":"Für den Reis"},{"name":"Karotte","amount":"1","unit":"","group":"Für den Reis"},{"name":"Erbsen","amount":"100","unit":"g","group":"Für den Reis"},{"name":"Eier","amount":"2","unit":"","group":"Für den Reis"},{"name":"Knoblauchzehen","amount":"2","unit":"","group":"Für den Reis"},{"name":"Frühlingszwiebeln","amount":"3","unit":"","group":"Für den Reis"},{"name":"Pflanzenöl","amount":"2","unit":"Esslöffel","group":"Für den Reis"},{"name":"Sojasauce","amount":"3","unit":"Esslöffel","group":"Für den Reis"},{"name":"Sesamöl","amount":"1","unit":"Teelöffel","group":"Für den Reis"},{"name":"Salz","amount":"1","unit":"Prise","group":"Für den Reis"},{"name":"schwarzer Pfeffer, gemahlen","amount":"1","unit":"Prise","group":"Für den Reis"}],"steps":[{"title":"Zutaten vorbereiten","content":"1 Karotte in kleine Würfel schneiden, 3 Frühlingszwiebeln in Ringe schneiden und 2 Knoblauchzehen hacken. 600 g gekochten, kalten Reis vom Vortag mit einer Gabel auflockern.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Gebratener Reis mit Gemüse: Zutaten vorbereiten"},{"title":"Gemüse anbraten","content":"2 Esslöffel Öl in einem Wok bei starker Hitze erhitzen und die Karotte und 100 g Erbsen 3 Minuten anbraten.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Gebratener Reis mit Gemüse: Gemüse anbraten"},{"title":"Ei zugeben","content":"Das Gemüse an den Rand schieben, 2 verquirlte Eier in die Mitte gießen und rühren, bis sie gestockt sind, etwa 1 Minute.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Gebratener Reis mit Gemüse: Ei zugeben"},{"title":"Knoblauch und Frühlingszwiebeln zugeben","content":"Knoblauch und die Hälfte der Frühlingszwiebeln zugeben und 30 Sekunden anbraten.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Gebratener Reis mit Gemüse: Knoblauch und Frühlingszwiebeln zugeben"},{"title":"Reis zugeben","content":"Den kalten Reis zugeben und 4 Minuten braten, dabei Klumpen mit dem Pfannenwender auflösen.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Gebratener Reis mit Gemüse: Reis zugeben"},{"title":"Würzen","content":"3 Esslöffel Sojasauce und 1 Teelöffel Sesamöl zugeben und 1 Minute vermengen.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Gebratener Reis mit Gemüse: Würzen"},{"title":"Abschmecken","content":"Abschmecken und mit Salz und Pfeffer nachwürzen; die Sojasauce salzt schon, daher nur wenig Salz verwenden.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Gebratener Reis mit Gemüse: Abschmecken"},{"title":"Servieren","content":"In einer Schüssel mit den restlichen Frühlingszwiebeln obenauf servieren.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Gebratener Reis mit Gemüse: Servieren"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Gebratener Reis mit Gemüse"}],"notes":"Frisch gekochter Reis ist feucht und klebt; verwende Reis vom Vortag, der im Kühlschrank gelagert wurde. Bei sehr starker Hitze und ohne den Wok zu überfüllen braten, damit der Reis Farbe bekommt, statt zu dämpfen. Man kann gewürfeltes Hähnchen, Garnelen oder gekochten Schinken ergänzen. Im Kühlschrank bis zu 3 Tage haltbar; in der Pfanne mit ein paar Tropfen Wasser aufwärmen.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 600 g gekochter weißer Reis, 80 g Karotte, 100 g Erbsen, 100 g Ei (2 Eier), 6 g Knoblauch, 45 g Frühlingszwiebel, 28 g Sojaöl, 48 g Sojasauce und 4,5 g Sesamöl. Das Salz und der Pfeffer am Ende werden nicht gezählt.","note":"Schätzung pro Portion. Der Reis wird als gekochter weißer Langkornreis berechnet. Das Natrium stammt fast vollständig aus der Sojasauce und steigt, wenn zusätzlich Salz verwendet wird."},"seo":{"title":"Gebratener Reis mit Gemüse, einfach und locker | Manual de Cocina","description":"Gebratener Reis mit Gemüse aus dem Wok, mit Karotte, Erbsen, Ei und Sojasauce. Für 4 Personen, fertig in 25 Minuten. Rezept Schritt für Schritt.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Warum nimmt man für gebratenen Reis Reis vom Vortag?","a":"Frisch gekochter Reis ist zu feucht und verklebt. Kalter, abgelagerter Reis ist trockener, bleibt körnig und bräunt im Wok besser."},{"q":"Kann man gebratenen Reis ohne Wok machen?","a":"Ja. Eine große, breite Pfanne bei starker Hitze verwenden und in kleinen Portionen braten, damit der Reis nicht dämpft."},{"q":"Wie lange hält sich gebratener Reis und wie wärmt man ihn auf?","a":"Bis zu 3 Tage im Kühlschrank in einem geschlossenen Behälter. In einer Pfanne mit ein paar Tropfen Wasser aufwärmen, bis er durch und durch heiß ist."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b5c3c304-0d87-5fc7-8516-7af016991f9e","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"en","slug":"vegetable-fried-rice","public_path":"/en/vegetable-fried-rice","source_url":null,"title":"Vegetable Fried Rice","excerpt":"Wok-style vegetable fried rice: fluffy rice with carrot, peas, egg and scallions, seasoned with soy sauce and sesame oil. Serves 4, ready in 25 minutes.","summary":"Vegetable fried rice is made by stir-frying carrot and peas in a very hot wok, scrambling beaten egg, adding garlic and scallions, and tossing everything with cold cooked rice. It is seasoned with soy sauce and a few drops of sesame oil.\n\nIt works best with day-old rice, which is dry and separates easily. The stir-frying takes about 10 minutes. It serves 4 as a side dish.","category":"Side dishes","difficulty":"Easy","course":"Side dish","cuisine":"Asian","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["vegetable fried rice","fried rice recipe","how to make fried rice","egg fried rice","chinese fried rice","easy fried rice","arroz frito con vegetales"],"ingredients":[{"name":"cold cooked white rice","amount":"600","unit":"g","group":"For the rice"},{"name":"carrot","amount":"1","unit":"","group":"For the rice"},{"name":"peas","amount":"100","unit":"g","group":"For the rice"},{"name":"eggs","amount":"2","unit":"","group":"For the rice"},{"name":"garlic cloves","amount":"2","unit":"","group":"For the rice"},{"name":"scallions","amount":"3","unit":"","group":"For the rice"},{"name":"vegetable oil","amount":"2","unit":"tablespoon","group":"For the rice"},{"name":"soy sauce","amount":"3","unit":"tablespoon","group":"For the rice"},{"name":"sesame oil","amount":"1","unit":"teaspoon","group":"For the rice"},{"name":"salt","amount":"1","unit":"pinch","group":"For the rice"},{"name":"ground black pepper","amount":"1","unit":"pinch","group":"For the rice"}],"steps":[{"title":"Prepare the ingredients","content":"Dice 1 carrot, slice 3 scallions and chop 2 garlic cloves. Fluff 600 g cold cooked rice from the day before with a fork.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Vegetable Fried Rice: Prepare the ingredients"},{"title":"Stir-fry the vegetables","content":"Heat 2 tablespoons oil in a wok over high heat and stir-fry the carrot and 100 g peas for 3 minutes.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Vegetable Fried Rice: Stir-fry the vegetables"},{"title":"Add the egg","content":"Push the vegetables to one side, pour 2 beaten eggs into the space and stir until set, about 1 minute.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Vegetable Fried Rice: Add the egg"},{"title":"Add the garlic and scallions","content":"Add the garlic and half of the scallions and stir-fry for 30 seconds.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Vegetable Fried Rice: Add the garlic and scallions"},{"title":"Add the rice","content":"Add the cold rice and stir-fry for 4 minutes, breaking up any clumps with the spatula.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Vegetable Fried Rice: Add the rice"},{"title":"Season","content":"Pour in 3 tablespoons soy sauce and 1 teaspoon sesame oil and toss for 1 minute.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Vegetable Fried Rice: Season"},{"title":"Adjust the seasoning","content":"Taste and adjust with salt and pepper; the soy sauce is already salty, so add only a little.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Vegetable Fried Rice: Adjust the seasoning"},{"title":"Serve","content":"Serve in a bowl with the remaining scallions on top.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Vegetable Fried Rice: Serve"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Vegetable Fried Rice"}],"notes":"Freshly cooked rice is moist and clumps; use rice cooked the day before and kept in the fridge. Cook over very high heat and do not overcrowd the wok, so the rice browns instead of steaming. You can add diced chicken, shrimp or cooked ham. Leftovers keep in the fridge for up to 3 days; reheat in a pan with a few drops of water.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 600 g cooked white rice, 80 g carrot, 100 g peas, 100 g egg (2 eggs), 6 g garlic, 45 g scallion, 28 g soybean oil, 48 g soy sauce and 4.5 g sesame oil. The final salt and pepper are not counted.","note":"Estimate per serving. The rice is calculated as cooked long-grain white rice. Sodium comes almost entirely from the soy sauce and rises if you add extra salt."},"seo":{"title":"Vegetable Fried Rice, Easy and Fluffy | Manual de Cocina","description":"Wok-style vegetable fried rice with carrot, peas, egg and soy sauce. Serves 4, ready in 25 minutes. Step-by-step recipe.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Why is fried rice made with day-old rice?","a":"Freshly cooked rice holds too much moisture and clumps. Cold, rested rice is drier, stays in separate grains and browns better in the wok."},{"q":"Can you make fried rice without a wok?","a":"Yes. Use a large, wide skillet over high heat and cook in small batches so the rice does not steam."},{"q":"How long does fried rice keep and how do you reheat it?","a":"Up to 3 days in the fridge in a closed container. Reheat in a pan with a few drops of water until piping hot all the way through."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"4b25e178-0f53-55b1-a5b4-bd24636f156d","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"fr","slug":"riz-saute-aux-legumes","public_path":"/fr/riz-saute-aux-legumes","source_url":null,"title":"Riz sauté aux légumes","excerpt":"Riz sauté aux légumes façon wok : riz bien égrené avec carotte, petits pois, œuf et ciboule, assaisonné de sauce soja et d'huile de sésame. Pour 4 personnes, prêt en 25 minutes.","summary":"Le riz sauté aux légumes se prépare en faisant sauter la carotte et les petits pois dans un wok très chaud, en faisant cuire des œufs battus, en ajoutant l'ail et la ciboule, puis en mélangeant le tout avec du riz cuit froid. On l'assaisonne de sauce soja et de quelques gouttes d'huile de sésame.\n\nIl est meilleur avec du riz cuit la veille, sec et facile à égrener. La cuisson au wok dure environ 10 minutes. Pour 4 portions en accompagnement.","category":"Accompagnements","difficulty":"Facile","course":"Accompagnement","cuisine":"Asiatique","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["riz sauté aux légumes","recette riz sauté","comment faire du riz sauté","riz sauté à l'œuf","riz cantonais","riz sauté facile","arroz frito con vegetales"],"ingredients":[{"name":"riz blanc cuit froid","amount":"600","unit":"g","group":"Pour le riz"},{"name":"carotte","amount":"1","unit":"","group":"Pour le riz"},{"name":"petits pois","amount":"100","unit":"g","group":"Pour le riz"},{"name":"œufs","amount":"2","unit":"","group":"Pour le riz"},{"name":"gousses d'ail","amount":"2","unit":"","group":"Pour le riz"},{"name":"ciboules","amount":"3","unit":"","group":"Pour le riz"},{"name":"huile végétale","amount":"2","unit":"cuillère à soupe","group":"Pour le riz"},{"name":"sauce soja","amount":"3","unit":"cuillère à soupe","group":"Pour le riz"},{"name":"huile de sésame","amount":"1","unit":"cuillère à café","group":"Pour le riz"},{"name":"sel","amount":"1","unit":"pincée","group":"Pour le riz"},{"name":"poivre noir moulu","amount":"1","unit":"pincée","group":"Pour le riz"}],"steps":[{"title":"Préparer les ingrédients","content":"Couper 1 carotte en petits dés, émincer 3 ciboules et hacher 2 gousses d'ail. Égrener à la fourchette 600 g de riz cuit froid de la veille.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Riz sauté aux légumes: Préparer les ingrédients"},{"title":"Faire sauter les légumes","content":"Chauffer 2 cuillères à soupe d'huile dans un wok à feu vif et faire sauter la carotte et 100 g de petits pois pendant 3 minutes.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Riz sauté aux légumes: Faire sauter les légumes"},{"title":"Ajouter l'œuf","content":"Pousser les légumes sur le côté, verser 2 œufs battus dans l'espace libre et remuer jusqu'à ce qu'ils prennent, environ 1 minute.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Riz sauté aux légumes: Ajouter l'œuf"},{"title":"Ajouter l'ail et la ciboule","content":"Ajouter l'ail et la moitié de la ciboule et faire sauter 30 secondes.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Riz sauté aux légumes: Ajouter l'ail et la ciboule"},{"title":"Ajouter le riz","content":"Ajouter le riz froid et faire sauter 4 minutes, en défaisant les grumeaux avec la spatule.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Riz sauté aux légumes: Ajouter le riz"},{"title":"Assaisonner","content":"Verser 3 cuillères à soupe de sauce soja et 1 cuillère à café d'huile de sésame et mélanger 1 minute.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Riz sauté aux légumes: Assaisonner"},{"title":"Rectifier l'assaisonnement","content":"Goûter et rectifier avec du sel et du poivre ; la sauce soja est déjà salée, n'en ajouter que très peu.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Riz sauté aux légumes: Rectifier l'assaisonnement"},{"title":"Servir","content":"Servir dans un bol avec le reste de ciboule par-dessus.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Riz sauté aux légumes: Servir"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Riz sauté aux légumes"}],"notes":"Le riz fraîchement cuit est humide et colle ; utilisez du riz cuit la veille et conservé au réfrigérateur. Cuire à feu très vif sans trop remplir le wok, pour que le riz dore au lieu de cuire à la vapeur. On peut ajouter du poulet, des crevettes ou du jambon cuit en dés. Se conserve au réfrigérateur jusqu'à 3 jours ; réchauffer à la poêle avec quelques gouttes d'eau.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 600 g de riz blanc cuit, 80 g de carotte, 100 g de petits pois, 100 g d'œuf (2 œufs), 6 g d'ail, 45 g de ciboule, 28 g d'huile de soja, 48 g de sauce soja et 4,5 g d'huile de sésame. Le sel et le poivre de la fin ne sont pas comptés.","note":"Estimation par portion. Le riz est calculé comme du riz blanc long grain cuit. Le sodium vient presque entièrement de la sauce soja et augmente si l'on ajoute du sel."},"seo":{"title":"Riz sauté aux légumes, facile et bien égrené | Manual de Cocina","description":"Riz sauté aux légumes façon wok, avec carotte, petits pois, œuf et sauce soja. Pour 4 personnes, prêt en 25 minutes. Recette pas à pas.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Pourquoi utiliser du riz de la veille pour le riz sauté ?","a":"Le riz fraîchement cuit contient trop d'humidité et colle. Un riz froid et reposé est plus sec, reste en grains séparés et dore mieux au wok."},{"q":"Peut-on faire du riz sauté sans wok ?","a":"Oui. Utiliser une grande poêle large à feu vif et cuire en petites quantités pour que le riz ne cuise pas à la vapeur."},{"q":"Combien de temps se conserve le riz sauté et comment le réchauffer ?","a":"Jusqu'à 3 jours au réfrigérateur dans un récipient fermé. Le réchauffer à la poêle avec quelques gouttes d'eau, jusqu'à ce qu'il soit bien chaud à cœur."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1a73305e-68b1-5535-aea6-ac7ac57b9f9f","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"it","slug":"riso-saltato-con-verdure","public_path":"/it/riso-saltato-con-verdure","source_url":null,"title":"Riso saltato con verdure","excerpt":"Riso saltato con verdure in stile wok: riso sgranato con carota, piselli, uovo e cipollotto, condito con salsa di soia e olio di sesamo. Per 4 persone, pronto in 25 minuti.","summary":"Il riso saltato con verdure si prepara saltando carota e piselli in un wok molto caldo, facendo rapprendere l'uovo sbattuto, aggiungendo aglio e cipollotto e mescolando tutto con riso cotto freddo. Si condisce con salsa di soia e qualche goccia di olio di sesamo.\n\nViene meglio con riso cotto il giorno prima, asciutto e facile da sgranare. La cottura in padella dura circa 10 minuti. Per 4 porzioni come contorno.","category":"Contorni","difficulty":"Facile","course":"Contorno","cuisine":"Asiatica","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["riso saltato con verdure","ricetta riso saltato","come fare il riso saltato","riso saltato con uova","riso alla cantonese","riso saltato facile","arroz frito con vegetales"],"ingredients":[{"name":"riso bianco cotto e freddo","amount":"600","unit":"g","group":"Per il riso"},{"name":"carota","amount":"1","unit":"","group":"Per il riso"},{"name":"piselli","amount":"100","unit":"g","group":"Per il riso"},{"name":"uova","amount":"2","unit":"","group":"Per il riso"},{"name":"spicchi d'aglio","amount":"2","unit":"","group":"Per il riso"},{"name":"cipollotti","amount":"3","unit":"","group":"Per il riso"},{"name":"olio di semi","amount":"2","unit":"cucchiaio","group":"Per il riso"},{"name":"salsa di soia","amount":"3","unit":"cucchiaio","group":"Per il riso"},{"name":"olio di sesamo","amount":"1","unit":"cucchiaino","group":"Per il riso"},{"name":"sale","amount":"1","unit":"pizzico","group":"Per il riso"},{"name":"pepe nero macinato","amount":"1","unit":"pizzico","group":"Per il riso"}],"steps":[{"title":"Prepara gli ingredienti","content":"Taglia 1 carota a dadini, affetta 3 cipollotti e trita 2 spicchi d'aglio. Sgrana con una forchetta 600 g di riso cotto freddo del giorno prima.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Riso saltato con verdure: Prepara gli ingredienti"},{"title":"Salta le verdure","content":"Scalda 2 cucchiai di olio in un wok a fuoco vivo e salta la carota e 100 g di piselli per 3 minuti.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Riso saltato con verdure: Salta le verdure"},{"title":"Aggiungi l'uovo","content":"Spingi le verdure da un lato, versa 2 uova sbattute nello spazio libero e mescola finché si rapprendono, circa 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Riso saltato con verdure: Aggiungi l'uovo"},{"title":"Aggiungi aglio e cipollotto","content":"Aggiungi l'aglio e metà del cipollotto e salta per 30 secondi.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Riso saltato con verdure: Aggiungi aglio e cipollotto"},{"title":"Aggiungi il riso","content":"Aggiungi il riso freddo e salta per 4 minuti, sciogliendo i grumi con la spatola.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Riso saltato con verdure: Aggiungi il riso"},{"title":"Condisci","content":"Versa 3 cucchiai di salsa di soia e 1 cucchiaino di olio di sesamo e mescola per 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Riso saltato con verdure: Condisci"},{"title":"Aggiusta di sapore","content":"Assaggia e aggiusta con sale e pepe; la salsa di soia è già salata, quindi aggiungine poco.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Riso saltato con verdure: Aggiusta di sapore"},{"title":"Servi","content":"Servi in una ciotola con il resto del cipollotto sopra.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Riso saltato con verdure: Servi"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Riso saltato con verdure"}],"notes":"Il riso appena cotto è umido e si impasta; usa riso cotto il giorno prima e conservato in frigorifero. Cuoci a fuoco molto vivo senza riempire troppo il wok, in modo che il riso si dori invece di cuocere al vapore. Puoi aggiungere pollo, gamberi o prosciutto cotto a dadini. Si conserva in frigorifero fino a 3 giorni; si riscalda in padella con qualche goccia d'acqua.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 600 g di riso bianco cotto, 80 g di carota, 100 g di piselli, 100 g di uovo (2 uova), 6 g di aglio, 45 g di cipollotto, 28 g di olio di soia, 48 g di salsa di soia e 4,5 g di olio di sesamo. Il sale e il pepe finali non sono conteggiati.","note":"Stima per porzione. Il riso è calcolato come riso bianco a grana lunga cotto. Il sodio proviene quasi tutto dalla salsa di soia e aumenta se si aggiunge sale."},"seo":{"title":"Riso saltato con verdure, facile e sgranato | Manual de Cocina","description":"Riso saltato con verdure in stile wok, con carota, piselli, uovo e salsa di soia. Per 4 persone, pronto in 25 minuti. Ricetta passo dopo passo.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Perché per il riso saltato si usa il riso del giorno prima?","a":"Il riso appena cotto contiene troppa umidità e si impasta. Il riso freddo e riposato è più asciutto, resta sgranato e si rosola meglio nel wok."},{"q":"Si può fare il riso saltato senza wok?","a":"Sì. Usa una padella grande e larga a fuoco vivo e cuoci a piccole dosi, in modo che il riso non cuocia al vapore."},{"q":"Quanto si conserva il riso saltato e come si riscalda?","a":"Fino a 3 giorni in frigorifero in un contenitore chiuso. Riscaldalo in padella con qualche goccia d'acqua finché è ben caldo anche all'interno."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a0db9cf0-b80c-5112-a5ca-b59149150fcb","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"ja","slug":"野菜チャーハン","public_path":"/ja/野菜チャーハン","source_url":null,"title":"野菜チャーハン","excerpt":"にんじん、グリーンピース、卵、ねぎを使い、しょうゆとごま油で味つけした、パラパラの野菜チャーハン。4人分、25分で完成。","summary":"野菜チャーハンは、よく熱した中華鍋でにんじんとグリーンピースを炒め、溶き卵を固め、にんにくとねぎを加えて、冷ましたご飯と全体を混ぜて作ります。しょうゆとごま油を数滴加えて味をととのえます。\n\n前日に炊いて水分の飛んだご飯を使うと、パラパラに仕上がります。炒める時間は約10分です。副菜として4人分です。","category":"付け合わせ","difficulty":"簡単","course":"副菜","cuisine":"アジア料理","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["野菜チャーハン","チャーハン レシピ","チャーハン 作り方","卵チャーハン","パラパラ チャーハン","チャーハン 簡単","アロス・フリト"],"ingredients":[{"name":"冷やご飯（白米）","amount":"600","unit":"g","group":"チャーハン用"},{"name":"にんじん","amount":"1","unit":"","group":"チャーハン用"},{"name":"グリーンピース","amount":"100","unit":"g","group":"チャーハン用"},{"name":"卵","amount":"2","unit":"","group":"チャーハン用"},{"name":"にんにく","amount":"2","unit":"","group":"チャーハン用"},{"name":"ねぎ","amount":"3","unit":"","group":"チャーハン用"},{"name":"サラダ油","amount":"2","unit":"大さじ","group":"チャーハン用"},{"name":"しょうゆ","amount":"3","unit":"大さじ","group":"チャーハン用"},{"name":"ごま油","amount":"1","unit":"小さじ","group":"チャーハン用"},{"name":"塩","amount":"1","unit":"ひとつまみ","group":"チャーハン用"},{"name":"黒こしょう（挽いたもの）","amount":"1","unit":"ひとつまみ","group":"チャーハン用"}],"steps":[{"title":"材料を準備する","content":"にんじん1本を角切りにし、ねぎ3本を小口切りにして、にんにく2片をみじん切りにします。前日に炊いた冷やご飯600gをフォークでほぐします。","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"野菜チャーハン: 材料を準備する"},{"title":"野菜を炒める","content":"中華鍋にサラダ油大さじ2を入れて強火で熱し、にんじんとグリーンピース100gを3分炒めます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"野菜チャーハン: 野菜を炒める"},{"title":"卵を加える","content":"野菜を片側に寄せ、あいたところに溶き卵2個を流し入れて、固まるまで約1分混ぜます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"野菜チャーハン: 卵を加える"},{"title":"にんにくとねぎを加える","content":"にんにくとねぎの半量を加え、30秒炒めます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"野菜チャーハン: にんにくとねぎを加える"},{"title":"ご飯を加える","content":"冷やご飯を加え、ヘラでほぐしながら4分炒めます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"野菜チャーハン: ご飯を加える"},{"title":"味つけする","content":"しょうゆ大さじ3とごま油小さじ1を回し入れ、1分混ぜます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"野菜チャーハン: 味つけする"},{"title":"味をととのえる","content":"味見をして、塩とこしょうでととのえます。しょうゆに塩分があるので、塩は控えめに加えます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"野菜チャーハン: 味をととのえる"},{"title":"盛り付ける","content":"器に盛り、残りのねぎをのせます。","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"野菜チャーハン: 盛り付ける"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"野菜チャーハン"}],"notes":"炊きたてのご飯は水分が多く、くっついてしまいます。前日に炊いて冷蔵庫に入れておいたご飯を使ってください。強火で、鍋に入れすぎないようにすると、ご飯が蒸されずにこんがり炒まります。角切りの鶏肉、えび、ハムを加えてもおいしいです。冷蔵庫で3日まで保存でき、フライパンに水を数滴加えて温め直します。","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。白米（炊いたもの）600g、にんじん80g、グリーンピース100g、卵100g（2個）、にんにく6g、ねぎ45g、大豆油28g、しょうゆ48g、ごま油4.5gを使用しています。最後に加える塩とこしょうは計算に含めていません。","note":"1人分の目安です。ご飯は炊いた長粒種の白米として計算しています。ナトリウムはほとんどがしょうゆに由来し、塩を足すと増えます。"},"seo":{"title":"野菜チャーハンの作り方｜パラパラで簡単 | Manual de Cocina","description":"にんじん、グリーンピース、卵、しょうゆで作る、パラパラの野菜チャーハン。4人分、25分で完成。手順を写真付きで解説します。","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"チャーハンに前日のご飯を使うのはなぜですか？","a":"炊きたてのご飯は水分が多くてくっつきます。冷めて落ち着いたご飯は水分が少なく、粒がばらけて、鍋でこんがり炒まります。"},{"q":"中華鍋がなくてもチャーハンは作れますか？","a":"作れます。大きくて広いフライパンを強火で熱し、ご飯が蒸れないよう少量ずつ炒めてください。"},{"q":"チャーハンはどれくらい保存でき、どう温め直しますか？","a":"密閉容器に入れて冷蔵庫で3日までです。フライパンに水を数滴加えて、中まで熱くなるまで温め直します。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"bf5b54dd-fc58-579c-8a68-3c02838af052","recipe_group_id":"5ffa87bc-2511-4121-b047-5d1f277bc536","language":"pt","slug":"arroz-frito-com-legumes","public_path":"/pt/arroz-frito-com-legumes","source_url":null,"title":"Arroz frito com legumes","excerpt":"Arroz frito com legumes ao estilo wok: arroz soltinho com cenoura, ervilhas, ovo e cebolinha, temperado com shoyu e óleo de gergelim. Para 4 pessoas, pronto em 25 minutos.","summary":"O arroz frito com legumes é feito salteando cenoura e ervilhas em uma wok bem quente, mexendo os ovos batidos até firmarem, juntando alho e cebolinha e misturando tudo com arroz cozido frio. É temperado com shoyu e algumas gotas de óleo de gergelim.\n\nFica melhor com arroz cozido no dia anterior, que está seco e solta bem. O salteado leva cerca de 10 minutos. Rende 4 porções como acompanhamento.","category":"Acompanhamentos","difficulty":"Fácil","course":"Acompanhamento","cuisine":"Asiática","prep_time_minutes":15,"cook_time_minutes":10,"total_time_minutes":25,"servings":4,"keywords":["arroz frito com legumes","receita de arroz frito","como fazer arroz frito","arroz frito com ovo","arroz frito chinês","arroz frito fácil","arroz frito con vegetales"],"ingredients":[{"name":"arroz branco cozido e frio","amount":"600","unit":"g","group":"Para o arroz"},{"name":"cenoura","amount":"1","unit":"","group":"Para o arroz"},{"name":"ervilhas","amount":"100","unit":"g","group":"Para o arroz"},{"name":"ovos","amount":"2","unit":"","group":"Para o arroz"},{"name":"dentes de alho","amount":"2","unit":"","group":"Para o arroz"},{"name":"cebolinhas","amount":"3","unit":"","group":"Para o arroz"},{"name":"óleo vegetal","amount":"2","unit":"colher de sopa","group":"Para o arroz"},{"name":"shoyu","amount":"3","unit":"colher de sopa","group":"Para o arroz"},{"name":"óleo de gergelim","amount":"1","unit":"colher de chá","group":"Para o arroz"},{"name":"sal","amount":"1","unit":"pitada","group":"Para o arroz"},{"name":"pimenta-do-reino moída","amount":"1","unit":"pitada","group":"Para o arroz"}],"steps":[{"title":"Prepare os ingredientes","content":"Corte 1 cenoura em cubinhos, fatie 3 cebolinhas e pique 2 dentes de alho. Solte com um garfo 600 g de arroz cozido frio do dia anterior.","image_url":"/recetas/arroz-frito-con-vegetales/paso-01.webp","image_alt":"Arroz frito com legumes: Prepare os ingredientes"},{"title":"Salteie os legumes","content":"Aqueça 2 colheres de sopa de óleo em uma wok em fogo alto e salteie a cenoura e 100 g de ervilhas por 3 minutos.","image_url":"/recetas/arroz-frito-con-vegetales/paso-02.webp","image_alt":"Arroz frito com legumes: Salteie os legumes"},{"title":"Junte o ovo","content":"Empurre os legumes para um lado, despeje 2 ovos batidos no espaço livre e mexa até firmarem, cerca de 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-03.webp","image_alt":"Arroz frito com legumes: Junte o ovo"},{"title":"Junte o alho e a cebolinha","content":"Junte o alho e metade da cebolinha e salteie por 30 segundos.","image_url":"/recetas/arroz-frito-con-vegetales/paso-04.webp","image_alt":"Arroz frito com legumes: Junte o alho e a cebolinha"},{"title":"Acrescente o arroz","content":"Acrescente o arroz frio e salteie por 4 minutos, desfazendo os torrões com a espátula.","image_url":"/recetas/arroz-frito-con-vegetales/paso-05.webp","image_alt":"Arroz frito com legumes: Acrescente o arroz"},{"title":"Tempere","content":"Despeje 3 colheres de sopa de shoyu e 1 colher de chá de óleo de gergelim e misture por 1 minuto.","image_url":"/recetas/arroz-frito-con-vegetales/paso-06.webp","image_alt":"Arroz frito com legumes: Tempere"},{"title":"Acerte o tempero","content":"Prove e acerte com sal e pimenta; o shoyu já é salgado, então use pouco sal.","image_url":"/recetas/arroz-frito-con-vegetales/paso-07.webp","image_alt":"Arroz frito com legumes: Acerte o tempero"},{"title":"Sirva","content":"Sirva em uma tigela com o restante da cebolinha por cima.","image_url":"/recetas/arroz-frito-con-vegetales/paso-08.webp","image_alt":"Arroz frito com legumes: Sirva"}],"image_url":"/recetas/arroz-frito-con-vegetales/portada.webp","gallery":[{"url":"/recetas/arroz-frito-con-vegetales/portada.webp","alt":"Arroz frito com legumes"}],"notes":"O arroz recém-cozido é úmido e empapa; use arroz cozido no dia anterior e guardado na geladeira. Cozinhe em fogo bem alto e sem encher demais a wok, para o arroz dourar em vez de cozinhar no vapor. Você pode juntar frango, camarão ou presunto em cubinhos. Dura na geladeira até 3 dias; reaqueça na frigideira com algumas gotas de água.","nutrition":{"calories":343,"protein_g":10.0,"carbs_g":50,"fat_g":11.2,"sodium_mg":713,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 600 g de arroz branco cozido, 80 g de cenoura, 100 g de ervilhas, 100 g de ovo (2 ovos), 6 g de alho, 45 g de cebolinha, 28 g de óleo de soja, 48 g de shoyu e 4,5 g de óleo de gergelim. O sal e a pimenta finais não são contados.","note":"Estimativa por porção. O arroz é calculado como arroz branco de grão longo cozido. O sódio vem quase todo do shoyu e aumenta se você juntar sal."},"seo":{"title":"Arroz frito com legumes, fácil e soltinho | Manual de Cocina","description":"Arroz frito com legumes ao estilo wok, com cenoura, ervilhas, ovo e shoyu. Para 4 pessoas, pronto em 25 minutos. Receita passo a passo.","image_variants":["/recetas/arroz-frito-con-vegetales/portada-1x1.webp","/recetas/arroz-frito-con-vegetales/portada-4x3.webp","/recetas/arroz-frito-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Por que o arroz frito é feito com arroz do dia anterior?","a":"O arroz recém-cozido tem muita umidade e empapa. O arroz frio e descansado é mais seco, fica soltinho e dora melhor na wok."},{"q":"Dá para fazer arroz frito sem wok?","a":"Dá. Use uma frigideira grande e larga em fogo alto e faça em porções pequenas, para o arroz não cozinhar no vapor."},{"q":"Quanto tempo dura o arroz frito e como reaquecer?","a":"Até 3 dias na geladeira em recipiente fechado. Reaqueça em uma frigideira com algumas gotas de água, até ficar bem quente por inteiro."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/arroz-frito') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
